// Des: Ingest social JSONL records (Facebook, Zalo) as stored pages
// Flo: list *.jsonl in the input folder > per line check kind, https url, text > dry-run only counts > live saves each record like a fetched page (raw file, page row, record row, outbox) > never refetch it > move the finished file to trash/<day>/ (the local purge empties it after purg_tras_days)
// I/O: input folder + db + config (caller) > Ires counts; so sync, purge, keepalive and the cars parser run unchanged on these records
// ===================================================================
const std = @import("std"); const cfgz = @import("cf-conf-load.zig"); const sqli = @import("st-stor-sqli.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const urln = @import("ut-urlz-norm.zig"); const soci = @import("pa-carz-soci.zig");
const civi = @import("ut-date-civi.zig");
const CF = .{ .ext = ".jsonl", .tras = "trash", .neve = @as(i64, 9_000_000_000_000_000) };
pub const Ires = struct { file: u32 = 0, line: u32 = 0, news: u32 = 0, chan: u32 = 0, same: u32 = 0, bads: u32 = 0 };
pub fn recoChek(aren: std.mem.Allocator, line: []const u8, maxz: u32) ?soci.Sock { if (line.len > maxz) return null; const rec = std.json.parseFromSliceLeaky(soci.Sock, aren, line, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return null; if (!std.mem.eql(u8, rec.kind, "face") and !std.mem.eql(u8, rec.kind, "zalo")) return null; if (!std.mem.startsWith(u8, rec.url, "https://") or std.mem.trim(u8, rec.text, " \t\r\n").len == 0) return null; return rec; }
fn neveSetz(dbzz: *sqli.Dbzz, urlz: []const u8) !void { var stmt = try dbzz.prep("UPDATE page SET next=?2 WHERE urlz=?1;"); defer stmt.fini(); try stmt.bindText(1, urlz); try stmt.bindIntz(2, CF.neve); _ = try stmt.step(); }
fn lineSavz(dbzz: *sqli.Dbzz, iozz: std.Io, dirz: []const u8, conf: cfgz.Conf, aren: std.mem.Allocator, rec: soci.Sock, line: []const u8, rslt: *Ires) !void { const norm = urln.urlzNorm(aren, rec.url) catch { rslt.bads += 1; return; }; const prev = try inde.pageGetz(dbzz, aren, norm); const outc = pipe.pageSave(aren, iozz, conf, dbzz, dirz, norm, prev, .{ .code = 200, .ctyp = "application/json", .body = line, .vend = "soci" }) catch { rslt.bads += 1; return; }; if (std.mem.eql(u8, outc.stat, "new")) { if (prev == null) rslt.news += 1 else rslt.chan += 1; } else if (std.mem.eql(u8, outc.stat, "same")) rslt.same += 1 else { rslt.bads += 1; return; } try neveSetz(dbzz, norm); }
fn fileMovz(dir: std.Io.Dir, iozz: std.Io, aren: std.mem.Allocator, dirz: []const u8, name: []const u8) !void { const nowz = pipe.nowzMill(iozz); var dbuf: [8]u8 = undefined; const newp = try std.fs.path.join(aren, &.{ dirz, CF.tras, civi.civiDayz(nowz, &dbuf), try std.fmt.allocPrint(aren, "social-{d}-{s}", .{ nowz, name }) }); const cwdz = std.Io.Dir.cwd(); if (std.fs.path.dirname(newp)) |dirn| try cwdz.createDirPath(iozz, dirn); try dir.rename(name, cwdz, newp, iozz); }
pub fn ingeRunz(dbzx: ?*sqli.Dbzz, iozz: std.Io, dirz: []const u8, srcd: []const u8, conf: cfgz.Conf, gpaz: std.mem.Allocator, dryz: bool) !Ires { var rslt: Ires = .{}; var aren = std.heap.ArenaAllocator.init(gpaz); defer aren.deinit(); const allo = aren.allocator();
    var dir = std.Io.Dir.cwd().openDir(iozz, srcd, .{ .iterate = true }) catch |err3| { if (err3 == error.FileNotFound) return rslt; return err3; }; defer dir.close(iozz);
    var names: std.ArrayList([]const u8) = .empty; var iter = dir.iterate(); while (try iter.next(iozz)) |item| { if (item.kind != .file or !std.mem.endsWith(u8, item.name, CF.ext)) continue; try names.append(allo, try allo.dupe(u8, item.name)); }
    for (names.items) |name| { rslt.file += 1; var far = std.heap.ArenaAllocator.init(gpaz); defer far.deinit(); const data = dir.readFileAlloc(iozz, name, far.allocator(), .limited(conf.soci_file_maxz)) catch { rslt.bads += 1; continue; }; var splz = std.mem.splitScalar(u8, data, '\n');
        while (splz.next()) |raw| { const line = std.mem.trim(u8, raw, " \t\r"); if (line.len == 0) continue; var lar = std.heap.ArenaAllocator.init(gpaz); defer lar.deinit(); const rec = recoChek(lar.allocator(), line, conf.soci_line_maxz) orelse { rslt.bads += 1; continue; }; rslt.line += 1; if (dryz) continue; try lineSavz(dbzx orelse return error.BadUsage, iozz, dirz, conf, lar.allocator(), rec, line, &rslt); }
        if (!dryz) try fileMovz(dir, iozz, allo, dirz, name); } return rslt; }
